def expand(items, w):
    out = []
    for it in items:
        if it == 'W':
            out.extend(w)
        elif it[0] == 'R':
            out.extend(SP(it[1]))
        else:
            out.append((it[1], it[2]))
    return tuple(out)


def expand_cfg(cfg, w):
    st, pb, A, g0, s, items, G = cfg
    return (st, pb, A, g0, s, expand(items, w), G)


def waypoints_rle(j, b):
    """The full asserted waypoint chain TOP9 -> ... -> TOP10
    (plus the r10 = 2 / 4 / 6 and band closing waypoints), in
    run-length form: pair lists are item lists ('P', a, b) /
    ('R', n) / 'W'.  Kept unexpanded -- at this phase's scale
    one expanded chain is ~19 GB of tuples."""
    r10 = 2 * j - 5703706
    j10 = j - 2851853
    tail = (('P', 1, 1), ('R', b - 1))
    pts = []
    pts.append(('C', TOP9F, 2020419, 2851850, 2,
                (('P', 2 * j - 2, 2),) + tail, 1))
    pts.append(('B', TOP9F, 2020418, 1, 2851850,
                (('P', 2, 2), ('P', 2 * j - 2, 2)) + tail, 1))
    pts.append(('C', F10, 2851850, 1, 2,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('B', F10, 2851850, 1, 4,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('C', F10, 2851850, 3, 2,
                (('P', 2 * j - 6, 2),) + tail, 1))
    pts.append(('C', F10, 0, 3, 2, (('R', 2851850), 'W'), 1))
    pts.extend(CASCADE56_WPS)
    # TOP10 state reached; closing waypoints by r10' = 2 * j10.
    if j10 == 1:
        pts.append(('B', (4042957,) + TOP10F, 5937476, 1, 3,
                    (('R', b - 1),), 1))
    if j10 == 2:
        pts.append(('C', TOP10F, 4042956, 5937474, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP10F, 4042955, 1, 5937474,
                    (('P', 2, 2), ('P', 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', (5937475, 4042956) + TOP10F, 3, 1, 3,
                    (('R', b - 1),), 1))
    if j10 == 3:
        pts.append(('C', TOP10F, 4042956, 5937474, 2,
                    (('P', 4, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP10F, 4042955, 1, 5937474,
                    (('P', 2, 2), ('P', 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F11, 5937474, 1, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', F11, 5937474, 1, 4,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', (5937475, 4042956) + TOP10F, 5, 1, 3,
                    (('R', b - 1),), 1))
    if j10 >= 4:
        pts.append(('C', TOP10F, 4042956, 5937474, 2,
                    (('P', 2 * j10 - 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', TOP10F, 4042955, 1, 5937474,
                    (('P', 2, 2), ('P', 2 * j10 - 2, 2),
                     ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('C', F11, 5937474, 1, 2,
                    (('P', 2 * j10 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F11, 5937474, 1, 4,
                    (('P', 2 * j10 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F11, 5937474, 3, 2,
                    (('P', 2 * j10 - 6, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F11, 5937474, 1, 2 * j10 - 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
    return pts


def check_chain(j, b, cap=60000000):
    """check_chain with lazy waypoint expansion (the Phase 56
    scale forbids materialising the whole chain).  Matching,
    skip recording and lemmastep replay verification are
    hsim55's, verbatim in behaviour."""
    rle = waypoints_rle(j, b)
    w = W(2 * j - 5703706, b)
    N = len(rle)
    cache = {}

    def target(k):
        if k not in cache:
            if len(cache) > 24:
                cache.clear()
            cache[k] = norm(expand_cfg(rle[k], w))
        return cache[k]

    pos = -1
    status = fin = None
    used = set()
    src = TOP9(j, b)
    anchor = norm(src)
    skips = []  # (anchor, [skipped waypoints], landing)
    for rec in swalk(src, max_steps=cap):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            status, fin, used = rec[1], rec[2], rec[3]
            break
        if pos + 1 < N:
            if _matches(rec, target(pos + 1)):
                pos += 1
                anchor = target(pos)
            else:
                for k in range(pos + 2, min(pos + 9, N)):
                    if _matches(rec, target(k)):
                        skips.append((anchor,
                                      [target(t)
                                       for t in range(pos + 1, k)],
                                      target(k)))
                        pos = k
                        anchor = target(pos)
                        break
    assert pos == N - 1, \
        'j=%d b=%d: waypoint %d missing: %s' \
        % (j, b, pos + 1, fmt(target(pos + 1)))
    for (anchor, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = anchor
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('verify replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'j=%d b=%d: skipped waypoint not verified: %s' \
            % (j, b, fmt(targets[ti]))
    return status, fin, pos, used


def front_check(j, b):
    """The front segment TOP9(j, b) -> DIP10 spine (waypoints
    0..5), with check_chain's skip recording + lemmastep
    replay verification and early exit at the spine."""
    rle = waypoints_rle(j, b)
    w = W(2 * j - 5703706, b)
    pts = [norm(expand_cfg(c, w)) for c in rle[:6]]
    pos = -1
    anchor = norm(TOP9(j, b))
    skips = []
    for rec in swalk(TOP9(j, b), max_steps=20000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if pos + 1 < len(pts):
            if _matches(rec, pts[pos + 1]):
                pos += 1
                anchor = pts[pos]
            else:
                for k in range(pos + 2, min(pos + 9, len(pts))):
                    if _matches(rec, pts[k]):
                        skips.append((anchor, pts[pos + 1:k],
                                      pts[k]))
                        pos = k
                        anchor = pts[pos]
                        break
        if pos == len(pts) - 1:
            break
    assert pos == len(pts) - 1, \
        'front j=%d b=%d: waypoint %d missing' % (j, b, pos + 1)
    for (a0, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = a0
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('front replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'front j=%d b=%d: skipped waypoint not verified' \
            % (j, b)


def TOP10(j10, b):
    return ('B', TOP10F, 4042956, 1, 5937475,
            ((2 * j10, 2), (1, 1)) + tuple(SP(b - 1)), 1)


def main():
    """Execution structure (Phase 56 scale): Part 1 (the
    canonical chain) and Part 1b (the junk-tail probe) are
    executed SPAN-SLICED via phase56-work/walkslice56.py
    (checkpointed slice queues phase56-work/jobs and
    jobs-junk; each slice replicates check_chain's matching
    and lemmastep skip-replay verification on its segment);
    Parts 1c, 2, 3, 4 below run directly in this process.
    Running this main() monolithically re-executes Part 1
    and 1b in-process (hours at this scale)."""
    fails = 0
    used = set()
    # Part 1: the canonical full waypoint chain (2851854, 2).
    try:
        status, fin, pos, u = check_chain(2851854, 2)
        used.update(u)
        print('PASS chain j=2851854 b=2: %d waypoints in order, '
              'walk %s' % (len(waypoints_rle(2851854, 2)), status),
              flush=True)
    except AssertionError as e:
        fails += 1
        print('FAIL', e, flush=True)
    # Part 1b: CASCADE56 is tail-general -- junk tail probe.
    w0 = ((7, 2), (1, 1), (3, 2), (1, 2))
    src = ('C', F10, 0, 3, 2, tuple(SP(2851850)) + w0, 1)
    top10 = norm(('B', TOP10F, 4042956, 1, 5937475, w0, 1))
    ok = False
    for rec in swalk(src, max_steps=60000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if norm(rec) == top10:
            ok = True
            break
    print(('PASS' if ok else 'FAIL'),
          'tail-generality: TOP10 shape reached with junk tail',
          flush=True)
    fails += 0 if ok else 1
    # Part 1c: front segments at the other chain points (the
    # cascade parse is (j, beta)-uniform: classifier chains
    # at beta = 2, 3 are identical; the cascade segment is
    # walk-verified at the canonical point and for the junk
    # tail above).
    for (j, b) in [(2851854, 3), (2851855, 2), (2851856, 2),
                   (3851853, 2), (8789330, 2)]:
        try:
            front_check(j, b)
            print('PASS front segment j=%d b=%d: TOP9 -> DIP10 '
                  'spine' % (j, b), flush=True)
        except AssertionError as e:
            fails += 1
            print('FAIL', e, flush=True)
    # Part 2: TOP10-closing finals (walks from the TOP10
    # state, whose stack is just W).
    F11p = (4042957,) + TOP10F
    F12p = (5937475, 4042956) + TOP10F
    finals = {
        (1, 2): (F11p, 5937477),
        (1, 3): (F11p, 5937478),
        (2, 2): (F12p, 4),
        (2, 3): (F12p, 5),
        (3, 2): (F12p, 6),
        (3, 3): (F12p, 7),
        (1000000, 3): (F12p, 2000001),
        (5937477, 2): (F12p, 11874954),
    }
    for (j10, b), (fr, A) in sorted(finals.items()):
        status = fin = None
        for rec in swalk(TOP10(j10, b), max_steps=60000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                status, fin, u = rec[1], rec[2], rec[3]
                used.update(u)
                break
        want = ('B', tuple(fr), A, 1, 2 * b + 1, (), 1)
        ok = status == 'DONE' and norm(fin) == want
        print(('PASS' if ok else 'FAIL'),
              'TOP10 final j10=%d b=%d: %s (want A=%d frame %s)'
              % (j10, b, fmt(fin), A, list(fr)), flush=True)
        fails += 0 if ok else 1
    # Part 3: the eleventh fence from the TOP10 state --
    # r10' >= 11874956 takes DIPGRIND at 5937474 (j10 is
    # TOP10's parameter).
    for (j10, b) in [(5937478, 2), (5937479, 2), (6148147, 2)]:
        g11 = norm(('C', F11, 5937474, 3, 2,
                    ((2 * j10 - 6, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        dip11 = norm(('C', F11, 0, 3, 2,
                      tuple(SP(5937474))
                      + ((2 * j10 - 11874954, 2), (1, 1))
                      + tuple(SP(b - 1)), 1))
        seen_g11 = seen_dip11 = False
        for rec in swalk(TOP10(j10, b), max_steps=60000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                break
            n = norm(rec)
            if n == g11:
                seen_g11 = True
            elif seen_g11 and n == dip11:
                seen_dip11 = True
                break
        ok = seen_g11 and seen_dip11
        print(('PASS' if ok else 'FAIL'),
              'fence j10=%d: GRIND11 then eleventh DIPGRIND '
              'landing occur (r10p=%d)' % (j10, 2 * j10),
              flush=True)
        fails += 0 if ok else 1
    # Part 4: primitive-step audit over the terminating
    # walks (the slice walks' records are produced by the
    # same mwalk/step_all; the classifier's step vocabulary
    # is exactly the PROVED_RULES lemma set).
    bad = used - PROVED_RULES
    print(('PASS' if not bad else 'FAIL'),
          'primitive rules used %s all in PROVED_RULES'
          % (sorted(used),), flush=True)
    fails += 0 if not bad else 1
    print()
    print('ALL PHASE 56 CHECKS PASS' if fails == 0
          else '%d FAILURES' % fails)
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
